class Solution:
    def sumOfPower(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        ans = 0
        prev = 0
        for x in sorted(nums):
            cur = (x + 2 * prev) % MOD
            ans = (ans + x * x % MOD * cur) % MOD
            prev = cur
        return ans

c.cpp:
class Solution {
public:
    int sumOfPower(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        sort(nums.begin(), nums.end());
        long long ans = 0, prev = 0;
        for (int x : nums) {
            long long cur = (x + 2 * prev) % MOD;
            ans = (ans + x % MOD * (x % MOD) % MOD * cur) % MOD;
            prev = cur;
        }
        return (int) ans;
    }
};

