var sumOfPower = function(nums) {
    const MOD = 1e9 + 7;
    nums.sort((a, b) => a - b);
    let ans = 0, prev = 0;
    for (const x of nums) {
        const cur = (x + 2 * prev) % MOD;
        ans = (ans + x * x % MOD * cur) % MOD;
        prev = cur;
    }
    return ans;
};
